class TenantBuffer {
  constructor(K) {
    this.K = K
    this.buffers = new Map()
  }
  enqueue(event) {
    const t = event.tenant_id
    if (!this.buffers.has(t)) this.buffers.set(t, [])
    const q = this.buffers.get(t)
    if (q.length >= this.K) return false
    q.push(event)
    return true
  }
  dequeue() {
    for (const [t, q] of this.buffers.entries()) {
      if (q.length) return q.shift()
    }
    return null
  }
}
```

